head.script:
scwin.onpageload = function() {
	$p.executeSubmission("submission1");
};

// WPFF-134: 자식 wframe 의 alias 컴포넌트가 부모 원본(dataList1·dataMap1·linkedDataList1)을 참조
scwin.checkAlias = function() {
	var frame = $p.getComponentById("w1");
	var aList = frame.getObj("ds_dataList1");
	var aMap = frame.getObj("ds_dataMap1");
	var aLinked = frame.getObj("ds_linkedDataList1");
	var cell = document.getElementById($p.id + "w1_gridView1_cell_0_0");
	if (!aList || !aMap || !aLinked || !cell) {
		return false;
	}
	return aList.getObj() === dataList1 && dataList1.getRowCount() > 0
		&& aList.getRowCount() == dataList1.getRowCount()
		&& cell.innerText === String(dataList1.getCellData(0, "col1"))
		&& aMap.get("key1") === dataMap1.get("key1") && dataMap1.get("key1") !== ""
		&& aLinked.getRowCount() == linkedDataList1.getRowCount();
};
